// Isolation test (OS-12) — construct RevisionLog with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import type { Currency, Unit } from "../src/catalog/index.js";
import { RevisionLog, type ConditionIdentity } from "../src/condition/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";

const u = "u1" as Unit;
const c = "c0" as Currency;
const X = "x" as ConditionIdentity;

describe("RevisionLog in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new RevisionLog({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new RevisionLog({ record: {} as never })).toThrow();
  });

  it("revise answers differently when record differs", () => {
    const busy = inMemoryRecord();
    busy.noise();
    expect(new RevisionLog({ record: inMemoryRecord() }).revise(u, c, X, "HUMAN")).not.toEqual(new RevisionLog({ record: busy }).revise(u, c, X, "HUMAN"));
  });

  it("revisions and conditionInForce answer differently when record differs", () => {
    const record = inMemoryRecord();
    const r = new RevisionLog({ record }).revise(u, c, X, "HUMAN");
    const empty = new RevisionLog({ record: inMemoryRecord() });
    expect(new RevisionLog({ record }).revisions(u, c, r.at)).not.toEqual(empty.revisions(u, c, r.at));
    expect(new RevisionLog({ record }).conditionInForce(u, c, r.at)).not.toEqual(empty.conditionInForce(u, c, r.at));
  });
});
